```javascript
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { cloneDeep } from 'lodash';

// Data types and interfaces
interface Customer {
  id: number;
  name: string;
}

interface Status {
  id: number;
  name: string;
}

interface Price {
  id: number;
  value: number;
}

interface Timeline {
  id: number;
  date: string;
  event: string;
}

interface Order {
  id: number;
  customer: Customer;
  status: Status;
  price: Price;
  timeline: Timeline[];
}

// Initial state
const initialState: { orders: Order[] } = {
  orders: [
    {
      id: 1,
      customer: { id: 1, name: 'John Doe' },
      status: { id: 1, name: 'Pending' },
      price: { id: 1, value: 100 },
      timeline: [
        { id: 1, date: '2022-01-01', event: 'Order placed' },
        { id: 2, date: '2022-01-02', event: 'Order shipped' },
      ],
    },
    {
      id: 2,
      customer: { id: 2, name: 'Jane Doe' },
      status: { id: 2, name: 'Shipped' },
      price: { id: 2, value: 200 },
      timeline: [
        { id: 1, date: '2022-01-01', event: 'Order placed' },
        { id: 2, date: '2022-01-02', event: 'Order shipped' },
      ],
    },
  ],
};

// Redux slice
const orderSlice = createSlice({
  name: 'orders',
  initialState,
  reducers: {
    updateTimeline(state, action: PayloadAction<{ orderId: number; event: Timeline }>) {
      const { orderId, event } = action.payload;
      const order = state.orders.find((order) => order.id === orderId);
      if (order) {
        order.timeline = cloneDeep(order.timeline);
        order.timeline.push(event);
      }
    },
  },
});

// Export actions and reducer
export const { updateTimeline } = orderSlice.actions;
export default orderSlice.reducer;

// Export data types/interfaces
export { Customer, Status, Price, Timeline, Order };
```

