        payload.put("iss", "your_issuer");
        payload.put("aud", "your_audience");
        payload.put("exp", new Date(System.currentTimeMillis() + 3600000)); // expires in 1 hour
        payload.put("iat", new Date(System.currentTimeMillis()));
        payload.put("sub", "your_subject");

        // Add the payload to the JWT builder
        jwtBuilder.setClaims(payload);

        // Sign the JWT with the private key
        String jwt = jwtBuilder.signWith(SignatureAlgorithm.RS256, privateKey).compact();

        System.out.println("Generated JWT: " + jwt);
    }
}
